from fastapi import FastAPI, HTTPException
from pydantic import BaseModel

app = FastAPI()

class Person(BaseModel):
    name: str
    email: str

registered = []
invited = []

@app.post('/register')
def register(p: Person):
    name = p.name.strip()
    if not name:
        raise HTTPException(status_code=400, detail='name is required')
    email = p.email.lower()
    record = {'name': name, 'email': email}
    registered.append(record)
    return record

@app.post('/invite')
def invite(p: Person):
    name = p.name.strip()
    if not name:
        raise HTTPException(status_code=400, detail='name is required')
    email = p.email.lower()
    record = {'name': name, 'email': email}
    invited.append(record)
    return record

