from fastapi import FastAPI, HTTPException
from pydantic import BaseModel

app = FastAPI()


class Person(BaseModel):
    name: str
    email: str


registered = []
invited = []


def normalize(p: Person):
    name = p.name.strip()
    if not name:
        raise HTTPException(status_code=400, detail='name is required')
    return {'name': name, 'email': p.email.lower()}


@app.post('/register')
def register(p: Person):
    record = normalize(p)
    registered.append(record)
    return record


@app.post('/invite')
def invite(p: Person):
    record = normalize(p)
    invited.append(record)
    return record


if __name__ == '__main__':
    import uvicorn
    uvicorn.run(app, port=8014)
